            'hostgroup': spec.hostgroup,
            'hbacsvc': list(spec.services),
            'hbacsvcgroup': list(spec.service_groups),
            'description': spec.rule_description,
            'managed': True,
            'created': existing is None,
        }
        return {
            'result': result,
            'summary': _format_summary(tenant, plan.rule_name),
        }


